def check_symptoms(symptoms):
    # IMPORTANT DISCLAIMER
    disclaimer = (
        'This is not a medical diagnosis. It provides general '
        'health information only. Consult a healthcare professional '
        'for medical advice. Call 999 for emergencies.'
    )

    # Match symptoms to common conditions
    matches = []
    for condition in CONDITIONS_DB:
        overlap = set(symptoms) & set(condition['symptoms'])
        if len(overlap) >= condition['min_match']:
            matches.append({
                'condition': condition['name'],
                'match_strength': len(overlap) / len(condition['symptoms']),
                'seek_urgent_care': condition.get('urgent', False),
            })

    return {
        'disclaimer': disclaimer,
        'possible_conditions': sorted(matches, key=lambda x: x['match_strength'], reverse=True)[:5],
        'recommendation': 'Please consult your GP for a proper assessment.',
        'emergency': any(m['seek_urgent_care'] for m in matches),
    }

This checker always includes disclaimers and never replaces professional medical advice.

def verify_age(date_of_birth, minimum_age=18):
    from datetime import date

    today = date.today()
    age = today.year - date_of_birth.year
    if (today.month, today.day) < (date_of_birth.month, date_of_birth.day):
        age -= 1

    return {
        'verified': age >= minimum_age,
        'age_stored': False,  # Do not store exact age
        'only_stored': 'over_18' if age >= 18 else 'under_18',
        'note': 'Data minimisation: store only the binary result, not the date of birth'
    }

def generate_support_response(user_message):
    # CRITICAL: Check for crisis indicators first
    if contains_crisis_indicators(user_message):
        return {
            'response': 'I hear you, and I want you to know that help is available right now. '
                       'Please contact the Samaritans on 116 123 (free, 24/7) or text SHOUT to 85258. '
                       'If you are in immediate danger, call 999.',
            'crisis_detected': True,
            'escalate_to_human': True,
        }

    # For non-crisis messages: validate, do not diagnose
    response = generate_empathetic_response(user_message)

    return {
        'response': response,
        'disclaimer': 'I am not a therapist. For professional support, contact your GP or find a therapist at bacp.co.uk.',
        'crisis_detected': False,
    }
